uv2 = uv + vec2(-1, 0.0 )*(vec2(1.0)/uTexSize);
float gx2 = GetPixel(uv2)*c.x + GetBlur1(uv2).xy*c.y + GetBlur2(uv2)*c.z + GetBlur3(uv2)*c.w;
